		public override void update()
		{
			base.update();
			FlxG.collide(player, blocks);
			FlxG.overlap<MonsterHans, Door>(monsters, interacts, monsterHansWithDoor);
			FlxG.overlap<Hans, BlockDiken>(player, dikens, dikeneBas);
			if (player.x >= 796 && player.y > 72)
			{
				player.x = 796;
			}
		}

		private void dikeneBas(Hans p, BlockDiken d)
		{
			player.moveEnable = false;
			player.jumpEnable = false;
			getHurt();
			player.velocity.x = 0;
		}

